## Fix for TOCTOU Race Condition in /tmp File Handling

```python
# Secure temporary file and lock utilities to prevent race conditions
import os
import tempfile
import stat
import time
import errno

class SecureTempFile:
    def __init__(self, prefix="tmp", dir="/tmp"):
        self.dir = dir
        self.prefix = prefix
        self.fd = None
        self.path = None

    def __enter__(self):
        self.fd, self.path = tempfile.mkstemp(
            prefix=self.prefix,
            dir=self.dir,
            suffix=".lock"
        )
        os.chmod(self.path, stat.S_IRUSR | stat.S_IWUSR)
        fstat = os.fstat(self.fd)
        assert fstat.st_uid == os.getuid()
        return self

    def write(self, data: bytes):
        os.write(self.fd, data)
        os.fsync(self.fd)

    def read(self) -> bytes:
        os.lseek(self.fd, 0, os.SEEK_SET)
        return os.read(self.fd, 4096)

    def get_path(self) -> str:
        return self.path

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.fd is not None:
            os.close(self.fd)
        if self.path and os.path.exists(self.path):
            os.unlink(self.path)

class SecureFileLock:
    def __init__(self, lock_path: str):
        self.lock_path = lock_path
        self.lock_fd, self.lock_temp = tempfile.mkstemp(
            dir=os.path.dirname(lock_path)
        )
        os.close(self.lock_fd)

    def acquire(self, timeout: float = 10.0) -> bool:
        start = time.time()
        while True:
            try:
                os.link(self.lock_temp, self.lock_path)
                return True
            except OSError as e:
                if e.errno != errno.EEXIST:
                    raise
                if time.time() - start > timeout:
                    return False
                time.sleep(0.01)

    def release(self):
        try:
            os.unlink(self.lock_path)
        except FileNotFoundError:
            pass
        finally:
            try:
                os.unlink(self.lock_temp)
            except FileNotFoundError:
                pass
